export default {"id":"spatial-level-0","number":0,"title":"Orientation","skillBand":"Textbook","duration":"From the course textbook","summary":"This document is the course map. It is not the lessons.","modules":[{"id":"spatial-m-1-1","code":"1","title":"Spatial Audio & Dolby Atmos — Course Syllabus","blurb":"This document is the course map. It is not the lessons.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"spatial-guide-overview","title":"Overview","blocks":[{"type":"step","title":"How to read this syllabus overview","blocks":[{"type":"heading","text":"Spatial Audio & Dolby Atmos — Course Syllabus","level":1},{"type":"prose","html":"<strong>Track id (proposed):</strong> <code>spatial-atmos</code>   <strong>Display title:</strong> Spatial Audio &amp; Dolby Atmos   <strong>Computers:</strong> <strong>Windows</strong> and <strong>macOS</strong> only. This course does not cover any other operating system.   <strong>Home DAW (this academy’s locked studio):</strong> Ableton <strong>Live 12 Standard</strong> + <strong>Operator</strong> + <strong>Max for Live</strong>   <strong>Status:</strong> Syllabus draft for approval. Not lesson content. Not wired into the app.   <strong>Quality bar:</strong> Textbook. Cited. No invented speaker counts, object limits, loudness numbers, buttons, or DAW features.   <strong>Grounding rule:</strong> Local library first (<code>B:\\Documents\\User Manuals\\Other Manuals\\Dolby Atmos for Win Config Guide.pdf</code>, Ableton Live 12 Standard Manual ch. <strong>17</strong> Routing, ch. <strong>18</strong> Mixing, ch. <strong>28</strong> Audio Effect Reference, Surround Panner notes in Max for Live production guidelines). Official Dolby, Apple, Microsoft, Ableton, Steinberg, UMG, and distributor pages fill gaps or settle conflicts. Unsupported or conflicting claims → <code>{type:'gap'}</code>."},{"type":"prose","html":"This document is the course map. It is <strong>not</strong> the lessons."},{"type":"prose","html":"<strong>Map size:</strong> 16 levels (0–15) · 48 modules · 214 core lessons · Gates A–J · Appendices A–D."}]}],"minutes":8}],"exercises":[]},{"id":"spatial-m-0-2","code":"0","title":"How to read this syllabus","blurb":"1. Work in order through Levels 0 → 15. Appendices are reference. 2. Every module lists learning outcomes, a full lesson table, mustCover / mustNotCover, primary sources, practice, and a checkpoint.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"spatial-guide-1","title":"How to read this syllabus","blocks":[{"type":"step","title":"0. How to read this syllabus","blocks":[{"type":"list","items":["Work in order through Levels 0 → 15. Appendices are reference.","Every module lists learning outcomes, a full lesson table, mustCover / mustNotCover, primary sources, practice, and a checkpoint.","Lessons are named <strong>Lesson X.Y.Z</strong> then a title and a one-sentence description. <strong>X</strong> = level, <strong>Y</strong> = module, <strong>Z</strong> = item. Authoring IDs (<code>atmos-l…</code>) are for later lesson files only; they are not learner-facing names.","Checkpoints are self-assessment. The desktop academy app cannot watch Live, Dolby Access, the Music app, or a renderer.","Depth registers (Plain / Standard / Technical) belong inside a future lesson step. They do not change the lesson count.","Sister courses:","<strong>Mastering Ableton Live 12</strong> — the stereo host, mixer, devices, export","<strong>Foundations of Music Production</strong> — song architecture","<strong>Sound Design Foundations</strong> — synthesis","<strong>Drums &amp; Rhythm Programming</strong> — groove","<strong>Building Max for Live Devices</strong> — writing devices (here: <em>use</em> Surround Panner)","<strong>AI Tools for Music Production</strong> — stem tools (this course <strong>forbids</strong> using stems extracted from a finished stereo as an Atmos source when Apple or a label forbids it)"],"ordered":true}]},{"type":"step","title":"0.1 Course spine","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Name the formats honestly → listen on Windows and on macOS →\nlearn beds, objects, renderer, ADM BWF →\nmake space in Live's stereo mixer (this is not Atmos) →\nuse Surround Panner for channel-based 4 / 6 / 8 (this is not Atmos) →\nmap official Atmos authoring hosts and the OS locks →\nif an official host is installed: beds, objects, binaural metadata, print →\nQC against published delivery specs → capstone</pre>"}]},{"type":"step","title":"0.2 Version honesty (locked)","blocks":[{"type":"table","headers":["Layer","Authority"],"rows":[["Dolby Access UI, profiles, Spatial Sound, Bluetooth/USB Effect Pack, Atmos for Speakers on Windows 11 24H2, HDMI home theater","Local <strong>Dolby Atmos for Windows Configuration Guide</strong>, 24 January 2025"],["What Dolby Atmos <em>is</em> (object-based, 3-D render, bitstream)","Same guide, ch. 8.1 + glossary"],["Windows Spatial Sound click path","Microsoft Support: <em>How to turn on spatial sound in Windows</em> (Windows 10 and Windows 11)"],["Apple Music playback on Mac and on Windows","Apple Support: <em>About Spatial Audio with Dolby Atmos in Apple Music</em> (4 April 2025); Music User Guide: <em>Play Spatial Audio with Dolby Atmos in Music on Mac</em>"],["Apple delivery rules (no upmix, no demix, stems from multitracks, secondary ISRC, Transporter)","Apple Music Provider Support: <em>Delivering Dolby Atmos audio</em>"],["Live mixer pan (Stereo / Split Stereo)","Live 12 Reference Manual ch. <strong>18</strong> (local PDF)"],["Auto Pan-Tremolo, Chorus-Ensemble Width","Ableton <em>Live Audio Effect Reference</em> (Live 12 web manual)"],["Surround Panner identity, 4 / 6 / 8 presets, XY / Rotate / Smooth / Focus / Center","Ableton pack page <em>Surround Panner</em>"],["Renderer input count, compatible DAWs, Mac vs Windows same-machine lock","Dolby Professional: <em>Dolby Atmos Renderer</em> product page"],["Music Panner formats and host list","Dolby Professional: <em>Dolby Atmos Music Panner</em>"],["Logic Pro native Atmos (macOS only)","Apple Logic Pro User Guide + Logic Pro tech specs"],["Label print numbers used in this map","UMG <em>Dolby Atmos Audio Servicing Asset Specifications</em> and <em>Best Practices</em>"],["Distributor print numbers used as a second published table","DistroKid Help: <em>Uploading a Dolby Atmos Mix of Your Music</em>"]],"caption":null},{"type":"prose","html":"Conflicts: official vendor pages win over paraphrased training PDFs. The local Dolby Access guide wins for <strong>Windows consumer playback clicks</strong>. Dolby Professional pages win for <strong>authoring</strong>. Apple Provider Support wins for <strong>what Apple will accept</strong>. If two official pages disagree on a versioned number, the lesson emits <code>{type:'gap'}</code> and the student records the date they re-read the page."}]},{"type":"step","title":"0.3 Suggested pace","blocks":[{"type":"table","headers":["Level","Focus","Duration","Gate"],"rows":[["0","What this course is; toolkit; OS lock","2–4 days","—"],["1","Names: Spatial Audio, Atmos, surround, Sonic","3–5 days","A"],["2","Channel layouts and height notation","3–5 days","—"],["3","Atmos architecture: beds, objects, renderer, files","1 week","B"],["4","Listen on Windows (Access + Spatial Sound + Music)","1 week","C"],["5","Listen on macOS (Music app)","3–7 days","D"],["6","Critical listening journal","1 week","E"],["7","Stereo space in Live (not Atmos)","1–2 weeks","F"],["8","Surround Panner (channel-based, not Atmos)","1 week","G"],["9","Official authoring hosts and OS locks","3–7 days","—"],["10","Authoring labs (gated by installed host)","1–3 weeks","H"],["11","Speaker vs headphone monitor; binaural metadata","1 week","—"],["12","Print specs (rate, bit depth, loudness, LFE)","3–7 days","I"],["13","ADM BWF export and QC","1 week","—"],["14","Delivery (Apple rules + published tables)","3–7 days","J"],["15","Capstone","2–4 weeks","Capstone"],["App","Dolby Access click book, source list, gap log","Optional","—"]],"caption":null}]},{"type":"step","title":"0.4 Academy rules this map obeys","blocks":[{"type":"list","items":["Library-grounded. No invented object counts, speaker angles, or “Live can print Atmos” claims.","Full module scaffolding, not a table of contents.","No lesson authoring until this syllabus is approved.","No fake auto-graders.","Project-based. Gate Capstone is a documented portfolio, not a badge.","Sister-course boundaries respected.","<strong>Windows and macOS only.</strong> Other operating systems are out of scope and are not named in teaching material.","Consumer playback enhancement (Dolby Access profiles, Windows Sonic) is <strong>not</strong> the same job as authoring a Dolby Atmos mix.","Surround Panner is <strong>not</strong> Dolby Atmos.","Stereo width in Live is <strong>not</strong> Dolby Atmos.","Apple forbids delivering an Atmos file that is only an upmix, a de-mix, or a stereo master parked in a 3-D field with added ambience."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"spatial-m-1-3","code":"1","title":"Locked product facts (do not drift)","blurb":"UMG servicing table (official label spec): DistroKid Help (distributor upload check) matches the loudness and true-peak pair (−18 LKFS / −1 dBTP, ITU-R BS.1770-4), requires BWF ADM, 24-bit LPCM at 48 kHz, 24 fps timecode, and stereo/Atmos s","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"spatial-guide-2","title":"Locked product facts (do not drift)","blocks":[{"type":"step","title":"1.1 What the words mean","blocks":[{"type":"table","headers":["Term","Locked meaning","Source"],"rows":[["<strong>Dolby Atmos</strong>","Object-based audio technology for creating and reproducing spatial audio. Individual audio objects can be preserved, transmitted, and rendered individually instead of being downmixed to a fixed channel count before transmission.","Local Dolby Access guide, ch. 8.1"],["<strong>Object-based audio</strong>","One or more audio signals plus metadata. Can contain <strong>bed objects</strong> (channel-based, fixed nominal playback position), <strong>dynamic objects</strong> with positional metadata that can change over time, and intermediate spatial-format objects. Linked to auditory image position rather than assumed loudspeaker positions.","Local guide, glossary"],["<strong>Spatial Audio</strong> (Apple’s wording)","How Apple refers to various <strong>playback</strong> technologies for immersive audio, <strong>including</strong> Dolby Atmos.","Apple Music Provider Support: <em>Delivering Dolby Atmos audio</em>"],["<strong>Dolby Atmos for Headphones / Speakers</strong>","Windows Spatial Sound formats exposed by Dolby Access on PCs that integrate Dolby Atmos for Windows.","Local guide, §2.1, §3.1"],["<strong>Windows Sonic for Headphones</strong>","Microsoft’s built-in Spatial Sound option on Windows 10 and Windows 11.","Microsoft Support spatial-sound article"],["<strong>Dolby Audio</strong>","Enhancement platform based on Dolby Digital Plus. Not the same product as Dolby Atmos authoring.","Local guide, ch. 8.2"],["<strong>Renderer</strong>","Application that takes beds + objects + metadata and renders them to the current monitor layout, and that writes Dolby Atmos master files. Official page: up to <strong>128</strong> inputs.","Dolby Professional Renderer page"],["<strong>ADM BWF</strong>","Audio Definition Model Broadcast Wave — the interchange / delivery master used by Apple, UMG, and DistroKid.","Apple Provider Support; UMG servicing specs; DistroKid Help"],["<strong>DAMF</strong>","Dolby Atmos Master File package (<code>.atmos</code> + <code>.atmos.metadata</code> + <code>.atmos.audio</code>). Closed Dolby package. Distinct from ADM BWF.","Library of Congress format description citing Dolby Renderer Guide"]],"caption":null}]},{"type":"step","title":"1.2 What this academy’s Live 12 Standard is and is not","blocks":[{"type":"table","headers":["Fact","Statement","Source"],"rows":[["Mixer pan","Default <strong>Stereo Pan Mode</strong> positions the track in the stereo field. <strong>Split Stereo Pan Mode</strong> (context menu) moves the left and right input channels separately.","Local manual ch. 18"],["Headroom","32-bit float tracks can go “into the red” internally; clipping matters when audio <strong>leaves</strong> Live (Main output, hardware I/O, export).","Local manual ch. 18"],["Native Atmos renderer","<strong>None.</strong> Live’s mixer is a stereo mixer.","ch. 18; no Atmos chapter in the Standard manual"],["Official Atmos path involving Live","Dolby lists <strong>Ableton Live</strong> as a Renderer-compatible DAW. That path <strong>requires the Dolby Atmos Music Panner</strong>.","Dolby Renderer page"],["Music Panner OS","AAX / AU / VST3 <strong>for Mac</strong>. Requires Renderer <strong>v5.0 or later</strong>. Tested in Live, Logic Pro X, Pro Tools Ultimate, Nuendo.","Dolby Music Panner page"],["Same-computer Renderer + DAW","<strong>Mac: Yes.</strong> <strong>Windows: No.</strong> Dolby Audio Bridge (needed to pass audio to the Renderer on one computer) is <strong>macOS only</strong>. On Windows the Renderer must run on a <strong>separate computer</strong> with a hardware route.","Dolby Renderer compatibility table"],["Surround Panner pack","Free Max for Live device. <strong>Requirements: Live 12 Standard &amp; Max for Live (12.0 or higher).</strong> Also listed as included with Live 12 Suite. XY panner; <strong>four-, six- and eight-channel</strong> presets. 2-D field.","Ableton <em>Surround Panner</em> pack page"],["Surround Panner ≠ Atmos","Channel-based, planar, 4 / 6 / 8. No beds, no objects, no ADM, no height metadata.","Same pack page vs Dolby 8.1 definition"]],"caption":null}]},{"type":"step","title":"1.3 Required vs gated tools","blocks":[{"type":"table","headers":["Tool","Role","Windows","macOS","Required?"],"rows":[["Live 12 Standard + Operator + Max for Live","Home DAW. Stereo space. Surround Panner host. Stem/multitrack prep for an Atmos host","Yes","Yes","<strong>Required</strong>"],["Closed-back or open headphones the student actually owns","Critical listening","Yes","Yes","<strong>Required</strong>"],["Windows Settings → System → Sound → Spatial sound","Built-in Sonic; also the place Dolby formats appear","Yes","—","Required on Windows"],["<strong>Dolby Access</strong> (Microsoft Store; preinstalled on some OEM PCs)","Configure Dolby Atmos for Headphones / Speakers / home theater","Yes","—","Required on Windows if the student wants the Dolby (not only Sonic) path. If Atmos is not on the device, Access shows a <strong>purchase page</strong> (local guide §3.1)"],["<strong>Apple Music</strong> app, current, signed in","Play catalog tracks that carry a Dolby Atmos badge","Yes (Apple’s Windows Music app)","Yes","Required for listening labs"],["Surround Panner pack","Channel-based 4 / 6 / 8 in Live","Yes","Yes","Required for Level 8 (free; needs Max for Live)"],["Logic Pro for Mac","Native Dolby Atmos plug-in, ADM BWF64 export/import","No","Yes","<strong>Gated.</strong> Not the academy home DAW"],["Dolby Atmos Renderer + Music Panner","External renderer; Live objects on Mac","Renderer: Yes (second PC). Panner: <strong>No</strong>","Yes (same Mac via Audio Bridge)","<strong>Gated</strong>"],["A native Atmos host on Windows (Dolby lists native partner integration in Nuendo, Cubase, Studio One, Pro Tools, Resolve, Pyramix)","Single-machine authoring on Windows","Host-dependent","Host-dependent","<strong>Gated.</strong> Do not invent clicks for a host the student does not have"],["HDMI + Dolby Atmos AVR / TV / sound bar","Home-theater playback from the PC","Yes","Yes","Optional listening lab"]],"caption":null},{"type":"prose","html":"<strong>Do not require:</strong> a 7.1.4 speaker room, a second Windows PC, Logic Pro, the paid Renderer, Pro Tools, Nuendo. Students without an authoring host still finish the course through listening, architecture, Live stereo space, Surround Panner, and delivery-spec literacy. Gate H and the ADM half of the capstone stay <strong>optional</strong>."}]},{"type":"step","title":"1.4 Published delivery numbers (re-read at lesson time)","blocks":[{"type":"prose","html":"UMG servicing table (official label spec):"},{"type":"table","headers":["Attribute","Value"],"rows":[["File container","ADM BWF"],["First Frame of Action (FFOA)","Prohibited"],["Duration","Matched to the corresponding stereo asset"],["Frame rate","<strong>24</strong>"],["Max channels","<strong>128</strong>"],["Bit depth","<strong>24</strong>"],["Sample rate","<strong>48 kHz</strong>, or <strong>96 kHz</strong> when natively created at 96 kHz"],["5.1 downmix mode","Direct Render"],["Binaural metadata","Required (not all “Off”)"],["Max integrated loudness","<strong>−18.0 LKFS</strong>"],["Max true peak","<strong>−1.0 dBTP</strong>"],["Integrated should not fall below","<strong>−31.0 LKFS</strong> on a 5.1 downmix (BT.1770-4), with the deliverable’s own 5.1 downmix and trim settings"],["LFE","If present, low-pass <strong>100–150 Hz</strong>"]],"caption":null},{"type":"prose","html":"DistroKid Help (distributor upload check) matches the loudness and true-peak pair (−18 LKFS / −1 dBTP, ITU-R BS.1770-4), requires BWF ADM, 24-bit LPCM at 48 kHz, 24 fps timecode, and stereo/Atmos same duration."},{"type":"prose","html":"Apple Provider Support does <strong>not</strong> put those loudness numbers on the public “Delivering Dolby Atmos audio” page. It <strong>does</strong> lock the creative rules in §1.5. At authoring time, re-read Apple’s current <em>Immersive Audio Source Profile</em> / <em>Video and Audio Asset Guide</em>. If Apple’s public number differs from UMG/DistroKid, <strong>cite both</strong> and follow the destination the student is actually delivering to."}]},{"type":"step","title":"1.5 Apple creative rules (locked)","blocks":[{"type":"prose","html":"From Apple Music Provider Support, <em>Delivering Dolby Atmos audio</em>:"},{"type":"list","items":["A Dolby Atmos track <strong>must</strong> be created from <strong>multitracks</strong> or <strong>stems created from multitracks</strong>.","<strong>Upmixing</strong> from a stereo release is <strong>not allowed</strong>.","<strong>Extracting stems (“de-mixing”)</strong> from a stereo release is <strong>not allowed</strong>.","A Dolby Atmos track that is <strong>only</strong> a stereo mix placed in the sound field with added ambience or reverb is <strong>not allowed</strong>.","Conform and sync the Atmos files with the <strong>stereo reference</strong> for the same project.","Deliver a unique <strong>secondary ISRC</strong>.","Delivery is through <strong>Transporter</strong>, or through a <strong>distributor / encoding house</strong> approved to deliver Dolby Atmos."],"ordered":false},{"type":"prose","html":"UMG Best Practices add label-side rejections that match Apple’s intent: stereo-only in an Atmos container; full-program material audible in every output; source separation used when stems/multitracks exist."}]},{"type":"step","title":"1.6 Windows Dolby Access product map (local guide)","blocks":[{"type":"prose","html":"Dolby Atmos for Windows configurations (one configuration per PC model; OEM partner machines):"},{"type":"list","items":["Dolby Atmos","Dolby Atmos Speaker System","Dolby Atmos for Gaming","Dolby Atmos Speaker System for Gaming"],"ordered":false},{"type":"prose","html":"Dolby Audio for Windows configurations (upgrade banner on HOME can offer Atmos):"},{"type":"list","items":["Dolby Audio","Dolby Audio Premium","Dolby Audio Speaker System"],"ordered":false},{"type":"prose","html":"Dolby Access tabs: <strong>HOME</strong> · <strong>PRODUCTS</strong> · <strong>SETTINGS</strong>. PRODUCTS exists on Atmos-for-Windows configurations. HDMI home theater appears on the PRODUCTS tab when HDMI is present. Info button on HOME shows OEM + configuration."},{"type":"prose","html":"<strong>Windows 11 version 24H2:</strong> Dolby Atmos for Speakers is available for built-in speakers <strong>and</strong> external speakers on 3.5 mm, USB, Bluetooth, HDMI, or DisplayPort. Earlier Windows versions labeled it Dolby Atmos for <strong>built-in</strong> speakers and limited it to built-in speakers."},{"type":"prose","html":"Profiles (Atmos configurations): <strong>Dynamic</strong> (no user controls; content-type auto), <strong>Game</strong>, <strong>Movie</strong>, <strong>Music</strong>, <strong>Voice</strong>, <strong>Custom</strong>. Intelligent Equalizer presets where offered: <strong>Detailed</strong>, <strong>Warm</strong>, <strong>Balanced</strong>. Game default EQ is <strong>Off</strong>. Performance Mode is on by default in Game; disable it to change Intelligent Equalizer."},{"type":"prose","html":"If Spatial sound is Off, Windows Sonic, or another third-party option, a <strong>subset</strong> of Dolby processing may still run in the legacy pipeline — the student is <strong>not</strong> receiving a Dolby Atmos experience (local guide §3.1)."}]},{"type":"step","title":"1.7 Apple Music playback on the two computers this course names","blocks":[{"type":"prose","html":"<strong>macOS</strong> (Apple Support, 4 April 2025 + Music User Guide):"},{"type":"list","items":["Update macOS.","Music → Settings (or Preferences) → <strong>Playback</strong> → Dolby Atmos: <strong>Automatic</strong>, <strong>Always On</strong>, or <strong>Off</strong>.","Automatic plays Atmos on any <strong>Apple or Beats Bluetooth headphones</strong>, and on built-in speakers of <strong>MacBook Pro (2018 or later)</strong>, <strong>MacBook Air (2018 or later)</strong>, <strong>iMac (2021)</strong>, or <strong>Apple Studio Display</strong>.","Other headphones: choose <strong>Always On</strong>.","Download: Settings → <strong>General</strong> → <strong>Download Dolby Atmos</strong>.","Per-song: while playing, click the Dolby icon → Audio Quality Settings.","If Atmos tracks sound quieter than stereo: enable <strong>Sound Check</strong> (Playback)."],"ordered":true},{"type":"prose","html":"<strong>Windows</strong> (same Apple article):"},{"type":"list","items":["Confirm with the PC maker that the hardware can play Dolby Atmos; Dolby Access may be required.","Update the Apple Music app.","Sidebar Actions → Settings → <strong>Playback</strong> → Dolby Atmos pop-up.","Settings → <strong>General</strong> → <strong>Download Dolby Atmos</strong>.","A stereo download is stored <strong>with</strong> an Atmos download; turn Dolby Atmos <strong>Off</strong> to hear stereo."],"ordered":true}]},{"type":"step","title":"1.8 Logic Pro (macOS only — gated authoring)","blocks":[{"type":"prose","html":"From Apple Logic Pro tech specs and release notes (re-read the installed version):"},{"type":"list","items":["Spatial Audio with Dolby Atmos is a Logic Pro feature. It is <strong>not</strong> a Live feature.","Bed formats listed on the tech-specs page: <strong>5.1 (ITU 775)</strong>, <strong>7.1</strong>, <strong>7.1.2</strong>. Logic Pro 11 notes later added <strong>5.1.0</strong> and <strong>7.1.0</strong> as surround bed formats.","Monitoring formats listed: <strong>Binaural (Dolby Renderer)</strong> and <strong>Apple Renderer</strong> (Spatial Audio profile).","Export: <strong>ADM BWF64</strong> compatible with Apple Music. Import: project from ADM BWF64 with bed + object tracks + metadata.","The Dolby Atmos plug-in lives on the <strong>surround master</strong> channel strip and renders bed + object outputs."],"ordered":false},{"type":"prose","html":"Do not teach Logic clicks as if they were Live clicks. Level 10 is gated."}]},{"type":"step","title":"1.9 What must not be taught as fact","blocks":[{"type":"list","items":["That Live 12 Standard can export an ADM BWF by itself.","That Surround Panner is “Ableton’s Atmos.”","That turning on Windows Sonic or a Dolby Access Music profile <strong>creates</strong> an Atmos mix.","That a stereo bounce plus Utility Width is Atmos.","That stem separation of a finished stereo (Moises, SpleeterGUI, Live Suite Stem Separation) is an allowed Apple Atmos source.","That Music Panner or Dolby Audio Bridge run on Windows.","That the Renderer and the DAW can share one Windows PC.","Any operating system other than Windows or macOS.","Invented speaker angles, ITU coordinates, or object-count “sweet spots” not on a cited page."],"ordered":false}]}],"minutes":13}],"exercises":[]},{"id":"spatial-m-0-1-2","code":"0.1","title":"— What this course is","blurb":"— What this course is","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"spatial-part-1-1","title":"What this course is","blocks":[{"type":"step","title":"Module 0.1 — What this course is","blocks":[{"type":"prose","html":"<strong>Outcomes.</strong> The student can state the three jobs in this course (listen, spatialize in stereo/channel-based Live, author Atmos only in an official host) and name the OS lock."},{"type":"table","headers":["ID","Lesson","One-sentence job"],"rows":[["0.1.1","Three different jobs","Separate <em>playback of</em> Atmos, <em>stereo/channel space in Live</em>, and <em>authoring</em> Atmos."],["0.1.2","Windows and macOS only","Write the OS lock into the lab log. Do not copy procedures from unnamed systems."],["0.1.3","Home DAW vs Atmos host","Live 12 Standard is the home DAW. An Atmos host is extra and may be absent."],["0.1.4","How a claim is sourced","Local manual → official vendor page → <code>{type:'gap'}</code>."],["0.1.5","Sister courses","Point to Live, production, stems, and M4L courses instead of duplicating them."]],"caption":null},{"type":"prose","html":"<strong>mustCover:</strong> the three-job split; OS lock; “no Atmos button in Live.”   <strong>mustNotCover:</strong> a promised 7.1.4 room; a required Logic purchase.   <strong>Primary sources:</strong> this §1; local Dolby guide ch. 8; Live ch. 18.   <strong>Practice:</strong> one-page “what I will and will not call Atmos.”   <strong>Checkpoint:</strong> student can reject the sentence “I’ll just bounce Live to Atmos.”"}]}],"minutes":8}],"exercises":[]},{"id":"spatial-m-0-2-3","code":"0.2","title":"— Open every tool and write what you have","blurb":"— Open every tool and write what you have","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"spatial-part-1-2","title":"Open every tool and write what you have","blocks":[{"type":"step","title":"Module 0.2 — Open every tool and write what you have","blocks":[{"type":"prose","html":"<strong>Outcomes.</strong> A filled toolkit sheet."},{"type":"table","headers":["ID","Lesson","One-sentence job"],"rows":[["0.2.1","Live edition and Max for Live","Confirm Standard (or Suite) + Max for Live so Surround Panner is legal."],["0.2.2","Windows Spatial Sound list","Settings → System → Sound → device → Spatial sound. Write every format the menu shows."],["0.2.3","Dolby Access present or not","Start menu. If missing, Microsoft Store. Record OEM / configuration from Info (HOME)."],["0.2.4","Apple Music signed in","Confirm the Music app opens on this Windows or Mac computer."],["0.2.5","Headphones and speaker path","Name the output device Live and the OS are actually using."],["0.2.6","Optional host census","Logic Pro / Renderer / Nuendo / Pro Tools / Cubase / Studio One: installed or not. No shame if not."]],"caption":null},{"type":"prose","html":"<strong>mustCover:</strong> write the <strong>actual</strong> Spatial Sound list; do not invent Dolby Atmos on a PC that only shows Windows Sonic.   <strong>mustNotCover:</strong> buying advice presented as a required purchase.   <strong>Primary sources:</strong> Microsoft spatial-sound article; local guide §2.1–2.3.   <strong>Practice:</strong> toolkit sheet in the project folder.   <strong>Checkpoint:</strong> every later lab can name the output device."}]}],"minutes":8}],"exercises":[]}]};
